const pasoResp = $json.data || [];
const paso     = pasoResp[0];
const original = $("Parse Model Output").item.json;

return [{
  json: {
    data: {
      fecha_reporte:        original.fecha_reporte,
      estado_general:       original.estado_general,
      fuente:               original.fuente,
      mensaje_original:     original.mensaje_original,
      confianza_extraccion: parseFloat(original.confianza_extraccion),
      origen_tipo:          original.origen_tipo,
      id_paso:              paso.id
    }
  }
}];

const raw =
  $json.text ?? $json.output ?? $json.response ??
  $json.result ?? $json.message ?? $json.content ?? $json;

let parsed;
let cleaned = raw;

if (typeof cleaned === "string") {
  cleaned = cleaned.replace(/```json\s*/g, "").replace(/```/g, "").trim();
  const start = cleaned.indexOf("{");
  const end   = cleaned.lastIndexOf("}");
  if (start !== -1 && end !== -1) cleaned = cleaned.slice(start, end + 1);
  parsed = JSON.parse(cleaned);
} else {
  parsed = cleaned;
}

if (!parsed || !parsed.items || !Array.isArray(parsed.items)) {
  throw new Error("No se encontró items[] en la salida del modelo. Output: " + JSON.stringify($json).slice(0, 500));
}

// Si items está vacío, el mensaje no tenía info fronteriza → saltar silenciosamente
if (parsed.items.length === 0) {
  return [{ json: { _skip: true, razon: "Gemini determinó que el mensaje no contiene estado fronterizo" } }];
}

// Metadata extra del mensaje original para enriquecer los registros
const msgMeta = {
  msg_timestamp: $input.item.json.msg_timestamp,
  msg_fecha_iso: $input.item.json.msg_fecha_iso,
  msg_id:        $input.item.json.msg_id,
  captured_at:   $input.item.json.captured_at
};

return parsed.items.map(item => ({
  json: {
    _skip: false,
    codigo_fuente:        item.codigo_fuente || null,
    fecha_reporte:        item.fecha_reporte || msgMeta.msg_fecha_iso || msgMeta.captured_at,
    estado_general:       item.estado_general || "desconocido",
    fuente:               item.fuente || "whatsapp_upf",
    mensaje_original:     item.mensaje_original || null,
    confianza_extraccion: parseFloat(item.confianza_extraccion) || 0.5,
    origen_tipo:          item.origen_tipo || "whatsapp_channel",
    // Campos extra para futura predicción
    _msg_timestamp: msgMeta.msg_timestamp,
    _msg_id:        msgMeta.msg_id
  }
}));

// Cada mensaje del canal es un item independiente para normalizar
const data = $json;
const mensajes = data.mensajes || [];

return mensajes.map(msg => ({
  json: {
    source_id: data.source_id,
    source_type: data.source_type,
    source_name: data.source_name,
    channel_label: data.channel_label,
    captured_at: data.captured_at,
    // Pasar el mensaje individual como array de 1 para el prompt de Gemini
    messages: [msg.body],
    // Metadata extra para enriquecer los registros y futuras predicciones
    msg_timestamp: msg.timestamp,
    msg_fecha_iso: msg.fecha_iso,
    msg_id: msg.id,
    msg_server_id: msg.server_id
  }
}));

const KEYWORDS = [
  "complejo", "fronterizo", "frontera", "habilitado", "cerrado", "abierto",
  "suspendido", "precaución", "precaucion", "habilitada", "cerrada",
  "región", "region", "paso", "horario", "ingreso", "salida", "vehículo",
  "vehiculo", "nevada", "tormenta", "nieve", "temporal", "temperatura",
  "hora", "hrs", "a.m.", "p.m.", "lunes", "martes", "miércoles", "jueves",
  "viernes", "sábado", "domingo", "ene", "feb", "mar", "abr", "may", "jun",
  "jul", "ago", "sep", "oct", "nov", "dic", "upf", "pino hachado",
  "los libertadores", "cardenal", "pehuenche", "jama", "colchane", "iquique",
  "pircas", "agua negra", "vergara", "pichachén", "pichachen", "hua hum",
  "caririñe", "san francisco", "dorotea", "casas viejas", "san sebastián",
  "bellavista", "integración austral", "don guillermo", "samoré", "samore"
];

function hasKeyword(text) {
  const lower = text.toLowerCase();
  return KEYWORDS.some(kw => lower.includes(kw));
}

const wahaMessages = Array.isArray($json) ? $json : [];
const metadata = $("Set Source Metadata").first().json;

// Filtrar mensajes con contenido fronterizo real
const relevantes = wahaMessages.filter(m => {
  if (!m.body || m.body.trim().length < 10) return false;
  return hasKeyword(m.body);
});

// Si no hay mensajes relevantes, retornar item vacío con flag
if (relevantes.length === 0) {
  return [{
    json: {
      sin_mensajes_relevantes: true,
      total_recibidos: wahaMessages.length,
      source_id: metadata.source_id,
      captured_at: metadata.captured_at
    }
  }];
}

// Agrupar mensajes por tanda diaria (misma fecha, publicados dentro de ~5 min entre sí)
// Ordenar por timestamp descendente (más recientes primero)
const sorted = relevantes.sort((a, b) => b.timestamp - a.timestamp);

// Extraer metadata útil de cada mensaje para predicciones futuras
const mensajesProcesados = sorted.map(m => ({
  id: m.id,
  body: m.body.trim(),
  timestamp: m.timestamp,
  fecha_iso: new Date(m.timestamp * 1000).toISOString(),
  server_id: m._data?.serverId || null,
  row_id: m._data?.rowId || null
}));

return [{
  json: {
    sin_mensajes_relevantes: false,
    source_id: metadata.source_id,
    source_type: metadata.source_type,
    source_name: metadata.source_name,
    channel_label: metadata.channel_label,
    captured_at: metadata.captured_at,
    total_recibidos: wahaMessages.length,
    total_relevantes: mensajesProcesados.length,
    mensajes: mensajesProcesados
  }
}];

